// ============ ELEMENTS ============
const $ = id => document.getElementById(id);
const homeView = $('homeView'), listView = $('listView'), storeView = $('storeView'), hero = $('hero');
const toastEl = $('toast');
let toastTimer, lastList = null;
let cart = []; // {key, name, price, emoji, photo, qty}

// ============ HELPERS ============
const fmt = p => '$' + p.toFixed(2);
const photoTag = url => url ? `<img src="${url}" alt="" loading="lazy" onerror="this.remove()">` : '';

function toast(msg) {
  toastEl.textContent = msg;
  toastEl.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.classList.remove('show'), 2200);
}

function showView(view) {
  [homeView, listView, storeView].forEach(v => v.hidden = v !== view);
  hero.hidden = view !== homeView;
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function setActiveCat(key) {
  document.querySelectorAll('.cat').forEach(c => c.classList.toggle('active', c.dataset.cat === key));
  document.querySelectorAll('.nav-links a').forEach(a => a.classList.toggle('active', a.dataset.nav === (key || 'home')));
}

function storeCard(store, catKey) {
  const card = document.createElement('div');
  card.className = 'store-card';
  card.innerHTML = `
    <div class="store-img${store.logo ? ' has-logo' : ''}" style="background:${store.logo ? store.logoBg : store.bg}"><span class="emo">${store.emoji}</span>${store.logo ? `<img class="logo-img" src="${store.logo}" alt="${store.name}">` : photoTag(store.photo)}</div>
    <button class="fav-btn" aria-label="Favorite">♡</button>
    <div class="store-body">
      <h4>${store.name}</h4>
      <div class="tag">${store.tag}</div>
      <div class="meta">
        <span><span class="star">★</span> ${store.rating} (${store.reviews})</span>
        <span>⏱ ${store.time} min</span>
      </div>
      <button class="order-btn">Order Now →</button>
    </div>`;
  card.querySelector('.fav-btn').addEventListener('click', e => {
    e.stopPropagation();
    const b = e.currentTarget;
    b.classList.toggle('on');
    b.textContent = b.classList.contains('on') ? '♥' : '♡';
    toast(b.classList.contains('on') ? `${store.name} added to favorites ❤️` : `${store.name} removed from favorites`);
  });
  card.addEventListener('click', () => openStore(catKey, store.id));
  return card;
}

// ============ VIEWS ============
function renderHome() {
  const wrap = $('homeStores');
  wrap.innerHTML = '';
  categories.restaurants.stores.forEach(s => wrap.appendChild(storeCard(s, 'restaurants')));
}

function openHome() {
  lastList = null;
  setActiveCat(null);
  $('searchInput').value = '';
  showView(homeView);
}

function openCategory(key) {
  lastList = () => openCategory(key);
  setActiveCat(key);
  $('listTitle').textContent = categories[key].title;
  $('catBanner').hidden = key !== 'supermarket';
  const wrap = $('listStores');
  wrap.innerHTML = '';
  categories[key].stores.forEach(s => wrap.appendChild(storeCard(s, key)));
  $('emptyMsg').hidden = true;
  showView(listView);
}

function openSearch(q) {
  lastList = () => openSearch(q);
  setActiveCat(null);
  $('listTitle').textContent = `Search results for "${q}"`;
  $('catBanner').hidden = true;
  const wrap = $('listStores');
  wrap.innerHTML = '';
  let found = 0;
  Object.entries(categories).forEach(([key, cat]) => {
    cat.stores.forEach(s => {
      if (s.name.toLowerCase().includes(q.toLowerCase()) || s.tag.toLowerCase().includes(q.toLowerCase())) {
        wrap.appendChild(storeCard(s, key));
        found++;
      }
    });
  });
  $('emptyMsg').hidden = found > 0;
  showView(listView);
}

function openStore(catKey, storeId) {
  const store = categories[catKey].stores.find(s => s.id === storeId);
  $('storeBanner').style.background = store.bg;
  $('storeBanner').innerHTML = `
    <div class="banner-text">
      <h2>${store.name}</h2>
      <p>${store.tag}</p>
      <p class="banner-meta">★ ${store.rating} (${store.reviews}) &nbsp;•&nbsp; ⏱ ${store.time} min</p>
    </div>
    ${store.logo
        ? `<div class="banner-logo" style="background:${store.logoBg}"><img src="${store.logo}" alt="${store.name}"></div>`
        : `<div class="banner-photo"><span class="emo">${store.emoji}</span>${photoTag(store.photo)}</div>`}`;

  const grid = $('menuGrid');
  grid.innerHTML = '';
  let lastSection = null;
  store.items.forEach(item => {
    if (item.section && item.section !== lastSection) {
      lastSection = item.section;
      const h = document.createElement('h4');
      h.className = 'menu-section';
      h.textContent = item.section;
      grid.appendChild(h);
    }
    const el = document.createElement('div');
    el.className = 'menu-item';
    el.innerHTML = `
      <div class="menu-emoji" style="${store.imgBg ? 'background:' + store.imgBg : ''}"><span class="emo">${item.emoji}</span>${photoTag(item.photo)}</div>
      <div class="menu-info">
        <h4>${item.name}</h4>
        <p>${item.desc}</p>
        <div class="menu-bottom">
          <strong>${fmt(item.price)}</strong>
          <button class="add-btn">+ Add</button>
        </div>
      </div>`;
    el.querySelector('.add-btn').addEventListener('click', () => addToCart(store, item));
    grid.appendChild(el);
  });
  showView(storeView);
}

// ============ CART ============
function addToCart(store, item) {
  const key = store.id + '|' + item.name;
  const found = cart.find(c => c.key === key);
  if (found) found.qty++;
  else cart.push({ key, name: item.name, price: item.price, emoji: item.emoji, photo: item.photo, store: store.name, qty: 1 });
  updateCart();
  toast(`${item.name} added to cart 🛒`);
}

function updateCart() {
  const count = cart.reduce((n, c) => n + c.qty, 0);
  const total = cart.reduce((n, c) => n + c.qty * c.price, 0);
  $('cartCount').textContent = count;
  $('cartTotal').textContent = fmt(total);

  const wrap = $('cartItems');
  if (!cart.length) { wrap.innerHTML = '<p class="empty">Your cart is empty 🛒</p>'; return; }
  wrap.innerHTML = '';
  cart.forEach(c => {
    const row = document.createElement('div');
    row.className = 'cart-row';
    row.innerHTML = `
      <div class="ce"><span class="emo">${c.emoji}</span>${photoTag(c.photo)}</div>
      <div class="ci"><b>${c.name}</b><small>${c.store} • ${fmt(c.price)}</small></div>
      <div class="qty"><button data-d="-1">−</button><span>${c.qty}</span><button data-d="1">+</button></div>`;
    row.querySelectorAll('button').forEach(b => b.addEventListener('click', () => {
      c.qty += Number(b.dataset.d);
      if (c.qty <= 0) cart = cart.filter(x => x !== c);
      updateCart();
    }));
    wrap.appendChild(row);
  });
}

function toggleCart(open) {
  $('drawer').classList.toggle('open', open);
  $('overlay').hidden = !open;
}

// ============ EVENTS ============
document.querySelectorAll('.cat').forEach(btn =>
  btn.addEventListener('click', () => openCategory(btn.dataset.cat)));

$('logo').addEventListener('click', openHome);
$('backHome').addEventListener('click', openHome);
$('backList').addEventListener('click', () => (lastList ? lastList() : openHome()));
$('seeAllRest').addEventListener('click', e => { e.preventDefault(); openCategory('restaurants'); });
$('orderNowBtn').addEventListener('click', e => { e.preventDefault(); openCategory('restaurants'); });
document.querySelectorAll('.nav-links a').forEach(a => a.addEventListener('click', e => {
  e.preventDefault();
  a.dataset.nav === 'home' ? openHome() : openCategory(a.dataset.nav);
}));
window.addEventListener('scroll', () => $('navbar').classList.toggle('scrolled', window.scrollY > 20));

$('searchInput').addEventListener('input', e => {
  const q = e.target.value.trim();
  q ? openSearch(q) : openHome();
});

$('cartLink').addEventListener('click', e => { e.preventDefault(); toggleCart(true); });
$('closeCart').addEventListener('click', () => toggleCart(false));
$('overlay').addEventListener('click', () => toggleCart(false));
$('checkoutBtn').addEventListener('click', () => {
  if (!cart.length) { toast('Your cart is empty'); return; }
  cart = []; updateCart(); toggleCart(false);
  toast('Order placed successfully 🎉');
});

// Location
const cities = ['Cairo', 'Alexandria', 'Giza', 'Damietta', 'Mansoura'];
let cityIdx = 0;
$('locationBtn').addEventListener('click', () => {
  cityIdx = (cityIdx + 1) % cities.length;
  $('cityName').textContent = cities[cityIdx];
  toast(`Delivering to ${cities[cityIdx]} 📍`);
});

// Track order
const stages = ['Order received', 'Preparing your order', 'Courier on the way', 'Delivered'];
let trackTimer;
$('trackForm').addEventListener('submit', e => {
  e.preventDefault();
  const no = $('orderNo').value.trim();
  if (!no) { toast('Please enter your order number'); return; }
  clearInterval(trackTimer);
  let step = 0;
  const draw = () => {
    $('trackResult').innerHTML = `<strong>Order #${no}</strong><ul class="steps">` +
      stages.map((s, i) => `<li class="${i <= step ? 'done' : ''}">${s}</li>`).join('') + '</ul>';
  };
  draw();
  trackTimer = setInterval(() => {
    step++;
    if (step >= stages.length) { clearInterval(trackTimer); return; }
    draw();
  }, 1500);
});

// ============ INIT ============
renderHome();
updateCart();